def main():
    index=json.loads((ROOT/'data/sources/officers/candidate_index.json').read_text(encoding='utf-8'))
    by_name={r['name']:q for q,r in index.items()}
    folder=ROOT/'data/master/officers'
    assessments=json.loads((folder/'assessments.json').read_text(encoding='utf-8')) if (folder/'assessments.json').exists() else {}
    for line in ROWS.strip().splitlines():
        name,values,refs,evidence,caveat,reasons,limited=line.split('|')
        if name not in by_name: raise ValueError('Missing officer: '+name)
        scores={k:int(v) for k,v in zip(['command','tactics','strategy','politics','trust'],values.split(','))}
        if by_name[name] in assessments: continue
        assessments[by_name[name]]={'status':'editorial_draft','cohort':'major_60','basis':'lifetime','scores':scores,'source_refs':refs.split(','),'evidence':evidence,'caveat':caveat,'score_reasons':dict(zip(scores,reasons.split(';'))),'score_confidence':{k:('limited_evidence' if k in limited.split(',') else 'editorial_estimate') for k in scores},'confidence':'provisional','score_method':'資料を手掛かりとした編集者のゲーム用比較案。1〜30点・1点刻み。出典が数値や全ての評価理由を保証するものではなく、推測を含む。'}
    folder=ROOT/'data/master/officers';folder.mkdir(parents=True,exist_ok=True)
    (folder/'assessments.json').write_text(json.dumps(assessments,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    existing_sources=json.loads((folder/'sources.json').read_text(encoding='utf-8')) if (folder/'sources.json').exists() else []
    existing_source_ids={r['id'] for r in existing_sources}
    (folder/'sources.json').write_text(json.dumps(existing_sources+[{'id':k,'title':v[0],'url':v[1],'accessed':'2026-09-12','use':'参照リンクと事実の短い要約。原文・画像を転載しない。'} for k,v in SOURCES.items() if k not in existing_source_ids],ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(len(assessments),'editorial assessments')

if __name__=='__main__':main()
